import sys,ctypes,random
sys.path[:0]=['site','submission'];ctypes.CDLL('native/libz.so.1',mode=ctypes.RTLD_GLOBAL)
from online_matching.train_rf import train_backup
from sklearn.tree import DecisionTreeClassifier
R=random.Random(0)
for q in range(100):
 c=R.randint(1,16);w=R.randint(2,16); rows=[]
 for k in range(c):
